for (const [name, english, slug, defense, immunity, resale, acquisition, restriction] of footwearAdditions) {
  const stats = `防御+${defense}；免疫+${immunity}`;
  entries.push({
    dataset: "items", slug, name, image: `/assets/game/${english.replaceAll(" ", "_")}.png`,
    summary: `${name}是可装备的鞋类，属性为${stats}。${restriction}`,
    attributes: {
      type: "鞋类", source: acquisition, sellPrice: `${resale}金（探险家公会）`,
      属性: stats, 获取方式: acquisition, 使用限制: restriction,
      主要用途: `装入鞋子栏后获得${stats}；不要只放在背包，也不要把出售价格当作购买价格。`,
      新手建议: `先比较现有鞋子的防御和免疫，再决定是否更换${name}；随机来源不能当作必定可用的开荒前提。`,
      关联规划: "推进矿井或姜岛时顺路寻找；缝纫可以转移鞋类属性，但定制外观不是额外一种基础鞋类。",
      资料来源: `https://stardewvalleywiki.com/${english.replaceAll(" ", "_")}`,
      links: ["/wiki/locations/adventurers-guild", "/guides/mines-floor-120-resource-monster-route", "/wiki/items"]
    }
  });
}

