for (const [slug, name, acquisition, recipe, restriction, sourceUrl, originalName] of hatAdditions) {
  let acquisitionGuide = recipe.startsWith("布料") ? `${acquisition}在已解锁的缝纫机中投入下列布料和材料制作。` : acquisition;
  if (slug.endsWith("-pan-hat")) acquisitionGuide += "先取得对应等级的淘盘，再从背包放入角色装备的帽子栏，形成该佩戴形态。";
  if (slug === "bucket-hat") acquisitionGuide += "在活动摊位逐个兑换金色标签，帽子属于轮换奖品，不保证第一次兑换得到。";
  acquisitionGuide = acquisitionGuide.replace(/。+/g, "。");
  entries.push({
    dataset: "items", slug, name, image: `/assets/game/Hat_${slug}.png`,
    summary: `${name}：${acquisitionGuide}`,
    attributes: {
      type: "帽子", 原名: originalName, source: acquisitionGuide, 获取方式: acquisitionGuide,
      制作配方: recipe, 基础售价: "不可出售",
      主要用途: `${name}用于角色外观搭配与帽子收藏；没有装备数值加成，不替代武器、鞋子或戒指。`,
      使用限制: restriction,
      新手建议: recipe.startsWith("布料") ? "缝纫会消耗布料和所选材料；先保留需要捐赠、献祭或交任务的那一份，再制作帽子。" : "先确认获取前提和对应商店或活动，不要只按售价寻找；随机掉落不保证一次就能获得。",
      关联规划: "根据成就、节日或材料来源安排收集顺序。已经取得的固定款式可以留作收藏，不需要为任意配色重复建立条目。",
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/festivals"]
    }
  });
}

