for (const [slug, name, originalName, bookType, first, repeat, acquisition, sell, sourceUrl] of bookAdditions) {
  const acquisitionGuide = acquisition + (acquisition.startsWith("书摊老板出售") ? "购买前先确认书摊老板的到访日期，不是每天都能购买。" : "");
  const restriction = slug === "book-of-stars"
    ? "五项技能均满10级后，本书转换为1125点精通经验；耕种经验只按一半转换，不是1250点。"
    : slug === "queen-of-sauce-cookbook"
      ? "只补齐酱料女皇节目的食谱，不是所有料理配方；友情、商店和技能来源的食谱仍需各自解锁。"
      : bookType === "能力书"
        ? "首次阅读才解锁对应能力；再次阅读不叠加同一种永久能力，是否增加经验以重复阅读说明为准。书籍会在使用后消耗。"
        : "每次阅读消耗一本书，获得对应技能经验；满级后的精通转换与未满级时的技能经验应分开理解。";
  entries.push({dataset: "items", slug, name, image: `/assets/game/Book_${slug}.png`,
    summary: `${name}：${first}`,
    attributes: {
      type: "书籍", 原名: originalName, 书籍类别: bookType, 首次阅读: first, 重复阅读: repeat,
      source: acquisitionGuide, 获取方式: acquisitionGuide, 基础售价: sell,
      主要用途: `${first}后续阅读效果：${repeat}应先确认自己是否已学会对应能力，再决定阅读、保留或出售。`,
      使用限制: restriction,
      新手建议: "购买前核对年份、解锁条件和当前已读状态。随机出现或随机掉落的来源不是每次必得，不要把书籍出售价格当作购买价格。",
      关联规划: "能力书优先考虑尚未掌握的能力；经验书按当前技能缺口安排。需要兑换、送礼或留存的书籍不要全部一次读掉。",
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/locations"]
    }
  });
}

