for (const [slug, name, originalName, purpose, acquisition, limitation, cost, materials, sourceUrl] of basicToolAdditions) {
  const acquisitionGuide = acquisition + (cost === "初始自带" ? "后续可在铁匠铺逐级升级，初始型号本身不要求金属锭。" : "");
  entries.push({dataset: "items", slug, name, image: `/assets/game/Tool_${slug}.png`,
    summary: `${name}：${purpose}`,
    attributes: {
      type: "基础工具与升级", 原名: originalName, 功能: purpose, 升级费用: cost, 所需材料: materials,
      source: acquisitionGuide, 获取方式: acquisitionGuide, 基础售价: "不适用，不能作为普通商品出售",
      主要用途: `${purpose}使用前应区分初始型号、普通升级等级与附魔效果，按实际工作目标选择工具。`,
      使用限制: limitation,
      新手建议: "安排升级前先完成当日必要工作并备齐金币与材料；商店购买、铁匠升级和探索奖励不是同一种获取方式。",
      关联规划: "按当前农场障碍、矿井深度和耕地规模安排升级。背包先解决携带容量，喷壶升级则需要提前安排缺工具期间的浇水。",
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/locations"]
    }
  });
}

