for (const [slug, name, originalName, type, purpose, limitation, recipeSource, materials, output, sell, sourceUrl] of craftFacilityAdditions) {
  const acquisition = `配方解锁：${recipeSource}。学会后消耗${materials}，单次制作${output}份；配方本身与成品是不同概念。`;
  entries.push({dataset: "items", slug, name, image: `/assets/game/Craft_${slug}.png`,
    summary: `${name}：${purpose}`,
    attributes: {
      type, 原名: originalName, 制作配方: materials, 配方解锁: recipeSource, 单次产量: output,
      source: acquisition, 获取方式: acquisition, ...(sell === null ? {} : { 基础售价: sell }),
      主要用途: `${purpose}使用时应按对应场景安排位置，并留出操作与通行空间。`,
      使用限制: limitation,
      新手建议: `先核对“${recipeSource}”这一解锁条件，再准备${materials}。商店的配方费用不包含制作时消耗的材料。`,
      关联规划: `按实际需要决定制作数量，每次配方产出${output}份。规划农场布局时保留通道，避免把照明、标记与自动化生产功能混为一谈。`,
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/locations"]
    }
  });
}

const specialCharacterAdditions = [
  ["birdie","贝啼","Birdie","姜岛西部海边小屋","解锁姜岛西部后，在非雨天前往最西侧海滩与她交谈，开启“海盗的妻子”交换任务。","交回海盗项链可完成她的任务；任务完成后仍能交谈，但不能把交换任务当作可反复送礼的友情系统。","下雨时不在屋外，且玩家不能进入她的小屋；先留好交换任务所需物品，再按任务线逐步交付。","https://stardewvalleywiki.com/Birdie"],
  ["bouncer","门卫","Bouncer","沙漠绿洲商店后方","到达沙漠并进入绿洲商店后，可在赌场入口见到门卫；进入赌场仍需完成“神秘的齐先生”任务线。","负责阻挡没有会员卡的玩家进入赌场；完成任务后让出入口，不提供生日、礼物或可培养的友情等级。","多人游戏各玩家需满足自己的会员卡条件，不能因另一位玩家已解锁就认为所有人均可进入。","https://stardewvalleywiki.com/Bouncer"],
  ["fizz","菲兹","Fizz","姜岛北部蘑菇洞","首次查看齐先生核桃房的完美度统计后，次日收到来信，再前往姜岛北部“水边洞穴”见他。","每份完美豁免花费500000金，增加1%完美度进展；豁免不是进入背包的实体物品，也不是完成对应任务本身。","购买前先比较剩余目标与预算；达到完美后他仍在洞内，但不能继续与他互动购买豁免。","https://stardewvalleywiki.com/Fizz"],
  ["gil","吉尔","Gil","深山探险家公会","满足探险家公会入会条件后，在公会营业期间进入，可在柜台旁的摇椅见到吉尔。","完成墙上海报对应的怪物击杀目标后，找他领取戒指、帽子等目标奖励；击杀进度和领奖动作需要分别确认。","先看公会海报的对应怪物数量，达标后再来领奖；普通交谈不会增加友情，也不需要准备生日礼物。","https://stardewvalleywiki.com/Gil"],
  ["governor","州长","Governor","夏威夷宴会活动场地；住址未公开","在每年的夏威夷宴会中可见到来访州长，他会品尝公共汤；也可能在电影院大厅出现。","在夏威夷宴会中评价公共汤，是节日汤料互动中的角色；不能把往汤里加入物品理解成对州长日常送礼。","选择汤料前核对节日规则与材料品质，不需要为州长安排日常生日或每周礼物计划。","https://stardewvalleywiki.com/Governor"],
  ["grandpa","爷爷","Grandpa","农场西北角爷爷的神龛（评价互动）","开场信件将农场留给玩家；第3年春季1日触发首次评价，此后可向农场西北神龛献钻石请求重评。","评价达到12分可点亮四根蜡烛，与神龛互动领取完美雕像；可获得的总分为21，不要求把所有项目全部完成。","首次评价不是游戏截止日期，错过四蜡烛也能继续发展并重评；评价分数不等于姜岛完美度百分比。","https://stardewvalleywiki.com/Grandpa"],
  ["gunther","冈瑟","Gunther","鹈鹕镇博物馆","带着可捐赠的矿物或古物首次进入博物馆，与冈瑟交谈开启捐赠介绍；之后在柜台办理藏品捐赠。","累计捐赠60件藏品后会带来生锈的钥匙；捐赠奖励按藏品进度触发，不是给冈瑟送友情礼物。","先核对藏品是否已捐赠，再决定出售或保留；不要把同一种矿物重复取得的数量当成新增藏品种类。","https://stardewvalleywiki.com/Gunther"],
  ["henchman","仆从","Henchman","女巫沼泽通往女巫小屋的道路","完成社区中心或Joja仓库路线，并推进“黑暗护身符”任务后，进入女巫沼泽即可遇到挡路的仆从。","向他交付虚空蛋黄酱解决“哥布林问题”，随后让开道路并离开；这是一次任务交付，不是可培养的日常好感。","可以通过图书馆遗失之书了解线索；交付前确认拿的是虚空蛋黄酱，普通蛋黄酱不能代替。","https://stardewvalleywiki.com/Henchman"],
  ["marlon","马龙","Marlon","深山探险家公会","初次进入矿井时遇见马龙并取得生锈的剑；完成入会任务后，可在探险家公会柜台使用商店与服务。","经营装备相关商店与物品找回服务；因生命值耗尽丢失物品后，可付费找回其中一项，不能一次恢复所有损失。","找回清单会被下一次生命值耗尽的掉落替换，应先处理最重要的损失；凌晨2点昏倒并不等同于战斗掉物品。","https://stardewvalleywiki.com/Marlon"],
  ["morris","莫里斯","Morris","鹈鹕镇Joja超市","Joja超市营业时进入店内，在右侧服务区找到莫里斯；商店仍营业时可与他办理Joja路线业务。","出售5000金的Joja会员资格；购买后社区中心改为仓库，改走社区发展付款路线，不能理解为普通购物折扣而忽略路线变化。","购买前先确认自己选择哪条发展路线；完成社区中心后Joja关店，莫里斯离开镇子，不再是固定可访问角色。","https://stardewvalleywiki.com/Morris"],
  ["mr-qi","齐先生","Mr. Qi","沙漠赌场与姜岛核桃房","在隧道锁箱放入电池组可开始神秘任务；完成对应任务取得赌场资格，累计找到100个金色核桃可进入姜岛核桃房。","提供赌场互动和姜岛特别挑战；完成核桃房挑战可得齐钻，赌场与核桃房是两套不同的进入条件和货币体系。","“找到100个金色核桃”不是向门口交付100个；核对各挑战条件与期限后再接单，不要把两处解锁要求混为一谈。","https://stardewvalleywiki.com/Mr._Qi"],
  ["professor-snail","蜗牛教授","Professor Snail","姜岛北部岛屿办事处","先花10个金色核桃修复通往挖掘场的桥，再用爆炸清除洞口岩石救出蜗牛教授，之后他回到岛屿办事处。","接受岛屿化石捐赠与调查问答，给予相应奖励；完成办事处全部要求可取得鸵鸟孵化器配方，不是普通博物馆捐赠。","带好爆炸工具再去洞口；岛屿化石应留给办事处核对，未救出教授前不能把洞穴当成已经营业的办事处。","https://stardewvalleywiki.com/Professor_Snail"],
  ["old-mariner","老水手","Old Mariner","海滩东侧潮池区域","开通海滩东侧通道后，在雨天06:00至19:00进入海滩可遇到老水手；冬季需雨水图腾，夜市期间仍不出现。","满足求婚条件时出售5000金的美人鱼吊坠：需与可结婚对象送过花束并达到10心，且农舍已进行首次升级。","人物出现与允许购买是两层条件；晴天等候不会出现，未升级农舍或未达到感情要求也不能仅靠金币购买。","https://stardewvalleywiki.com/Old_Mariner"],
];
for (const [slug, name, originalName, address, acquisition, purpose, advice, sourceUrl] of specialCharacterAdditions) {
  entries.push({ dataset: "villagers", slug, name, image: `/assets/game/NPC_${slug}.png`, summary: purpose,
    attributes: { type: "特殊角色", 原名: originalName, birthday: "未公开（无生日送礼机制）", address,
      loves: "不适用：无常规友情送礼机制", 交互限制: "不能通过每周送礼培养好感；剧情交付、藏品捐赠与购买服务不属于友情礼物。",
      获取方式: acquisition, 主要用途: purpose, 新手建议: advice,
      关联规划: "按角色所在区域和任务前置安排访问，先确认已解锁对应场景；不要套用普通村民生日送礼计划。",
      资料来源: sourceUrl, links: ["/wiki/villagers", "/wiki/quests", "/wiki/locations"] }
  });
}

const consumableAdditions = [
  ["field-snack","工作小食","Field Snack","采集1级","橡子×1、枫树种子×1、松果×1","恢复45能量与20生命值。","这是打造食品，不属于厨房烹饪配方；原料种子也可用于种树，需按木材需求留种。",20,"https://stardewvalleywiki.com/Field_Snack"],
  ["bug-steak","虫肉块","Bug Steak","战斗1级","虫肉×10","恢复45能量与30生命值。","会消耗本可用来制造鱼饵的虫肉；不是用虫肉直接恢复生命，也不是村民通用礼物。",50,"https://stardewvalleywiki.com/Bug_Steak"],
  ["life-elixir","生命药水","Life Elixir","战斗2级","红蘑菇×1、紫蘑菇×1、羊肚菌×1、鸡油菌×1","生命值恢复至满值，不恢复能量。","1.6.4起不再恢复能量；不要沿用旧版200能量和固定90生命值的说明。矮人处成品售价为2000金，非出售回收价。",250,"https://stardewvalleywiki.com/Life_Elixir"],
  ["oil-of-garlic","蒜油","Oil of Garlic","战斗6级","大蒜×10、油×1","恢复200能量与89生命值，特殊驱怪效果持续现实时间10分钟。","普通矿井中阻止生成敌人，但不包括地牢层；骷髅洞穴阻止怪物层与怪群，不排除史前层；危险矿井与危险骷髅洞穴无效。",1000,"https://stardewvalleywiki.com/Oil_of_Garlic"],
  ["monster-musk","怪兽香水","Monster Musk","完成法师特别订单“五彩胶冻”","蝙蝠翅膀×30、史莱姆泥×30","持续现实时间10分钟；进入矿井或骷髅洞穴的新楼层时，使该层生成的敌人数量翻倍。","不会把当前已出现的每只怪物直接复制；火山、采石场矿洞、突变虫穴的日末重置区域不能照搬同样的入层效果。",50,"https://stardewvalleywiki.com/Monster_Musk"],
  ["fairy-dust","仙尘","Fairy Dust","完成贝啼“海盗的妻子”任务","钻石×1、玫瑰仙子×1","使适用机器当前正在进行的加工阶段立即完成；每次使用消耗一份仙尘。","木桶熟成每次只提升到下一个品质，不能从普通直接变铱星；普通、鸵鸟、史莱姆孵化器均不适用。",300,"https://stardewvalleywiki.com/Fairy_Dust"],
  ["warp-totem-beach","传送图腾：海滩","Warp Totem: Beach","采集6级","硬木×1、珊瑚×2、纤维×10","一次性传送至海滩的指定落点。","夏威夷宴会或月光水母起舞当天、节日尚未开始前使用，会消耗图腾但无法传送到海滩。",20,"https://stardewvalleywiki.com/Warp_Totem:_Beach"],
  ["warp-totem-mountains","传送图腾：山岭","Warp Totem: Mountains","采集7级","硬木×1、铁锭×1、石头×25","一次性传送至深山的指定落点。","使用后即消耗，不是永久传送建筑，也不直接把玩家送进矿井任意层数。",20,"https://stardewvalleywiki.com/Warp_Totem:_Mountains"],
  ["warp-totem-farm","传送图腾：农场","Warp Totem: Farm","采集8级","硬木×1、蜂蜜×1、纤维×20","一次性传送至农场的指定落点。","不要与回程魔杖或姜岛农场图腾柱混淆；赌场1.6价格是1000齐币，不是1000金币。",20,"https://stardewvalleywiki.com/Warp_Totem:_Farm"],
  ["warp-totem-desert","传送图腾：沙漠","Warp Totem: Desert","沙漠商人处以10铱锭换取配方","硬木×2、椰子×1、铱矿石×4","一次性传送至沙漠的指定落点。","配方兑换与成品兑换不同：成品可用3万能晶球兑换；传送到沙漠不等于自动获得骷髅洞穴钥匙。",20,"https://stardewvalleywiki.com/Warp_Totem:_Desert"],
  ["warp-totem-island","传送图腾：姜岛","Warp Totem: Island","火山矮人处购买配方，10000金","硬木×5、龙牙×1、姜×1","一次性传送至姜岛的指定落点。","制造一份需要消耗龙牙；不会自动解锁岛上桥梁、农舍等设施，应先规划返程与区域开通。",20,"https://stardewvalleywiki.com/Warp_Totem:_Island"],
  ["rain-totem","雨水图腾","Rain Totem","采集9级","硬木×1、松露油×1、松焦油×5","将使用地区次日天气设为雨天；消耗一个图腾。","仅影响使用所在地区；无法覆盖鹈鹕镇节日或换季第1天的固定天气。1.6起不能连锁雷暴以持续获取电池组。",20,"https://stardewvalleywiki.com/Rain_Totem"],
  ["treasure-totem","宝藏图腾","Treasure Totem","领取采集精通奖励","硬木×5、神秘糖浆×1、苔藓×10","在室外可挖掘地面使用，周围最多生成16个远古斑点。","1.6.4起不能在室内使用；有障碍或不可挖掘的格子不会生成斑点，不保证每次都出现16处。",20,"https://stardewvalleywiki.com/Treasure_Totem"],
];
for (const [slug, name, originalName, recipe, materials, effect, limitation, sell, sourceUrl] of consumableAdditions) {
  const acquisition = `配方解锁：${recipe}。学会后每次消耗${materials}，制作一份成品；解锁配方不会自动赠送无限材料。`;
  entries.push({ dataset: "items", slug, name, image: `/assets/game/Consumable_${slug}.png`, summary: `${name}：${effect}`,
    attributes: { type: "可制作消耗品", 原名: originalName, 配方解锁: recipe, 制作配方: materials,
      效果: effect, source: acquisition, 获取方式: acquisition, sellPrice: `${sell}金`, 基础售价: `${sell}金`,
      主要用途: `${effect}使用前先核对适用场景和限制，避免消耗后不能达到原先目的。`, 使用限制: limitation,
      新手建议: limitation,
      关联规划: `按当天探索或生产目标准备数量，原料${materials}也可能有其他用途，不要把一次性消耗品当成永久设备。`,
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/locations"] }
  });
}

