for (const [slug, name, gameId, type, originalName, englishName, spriteIndex, canDye, acquisition, randomPrismatic, image, source, nativeBase, characterCreation] of verifiedClothingAdditions) {
  const makingNote = randomPrismatic
    ? "布料加五彩碎片会在五种五彩服饰中随机生成，可能重复，不能指定这一个结果。"
    : "先核对物品编号和获取途径；同名不同款式不一定能用相同材料制作，缝纫材料按每次一份消耗。";
  entries.push({ dataset: "items", slug, name, image,
    summary: acquisition + (canDye ? "此款支持染色。" : "此款不能染色。"),
    attributes: { type, 原名: originalName, 英文名: englishName, 游戏物品编号: gameId, 图片索引: spriteIndex,
      可染色: canDye ? "是" : "否", 出售限制: "不可出售", 获取方式: acquisition,
      创建角色可选: characterCreation ? "是" : "否", 制作提醒: makingNote,
      主要用途: "装备于对应服装栏改变角色外观；上衣和下装不提供防御、免疫或技能加成，不应当作战斗装备。",
      新手建议: "首次取得布料后，在符合条件的晴天触发艾米丽介绍缝纫的事件；先确认材料用途，再把任务物品或稀有材料投入缝纫机。",
      关联规划: "可将服饰存入梳妆台整理；染色变化不另算新的固定款式，收集时按物品编号区分同名衣服。",
      图片说明: nativeBase ? "游戏原始未染色正面底图；换装服务的实际颜色可能不同。" : "对应款式图示；可染色衣物的成品颜色可能随原料或后续染色变化。",
      资料来源: source, 版本依据: "本机原版1.6.15.24356数据与缝纫/单项来源交叉核对。",
      links: ["/wiki/items", "/wiki/villagers"] }
  });
}

const specialEquipmentAdditions = [
  ["coffee-maker","咖啡机","Coffee Maker","完成艾芙琳的特别任务“给乔治的礼物”后收取邮件。","每天早晨自动生成一杯咖啡，无须投入咖啡豆。","不能当成小桶批量投入原料；遗失后可在秘密森林遗失物品商店花10000金补购。","每天早晨","https://stardewvalleywiki.com/Coffee_Maker"],
  ["deconstructor","分解机","Deconstructor","在齐先生的核桃房花20颗齐钻购买成品，不是学习打造配方。","拆解适用打造物，返还其配方中最有价值的一类原料。","不是返还全部材料；投入的成品会被销毁，只有机器接受的物品才能拆解。","60游戏分钟","https://stardewvalleywiki.com/Deconstructor"],
  ["sewing-machine","缝纫机","Sewing Machine","完成艾米丽的特别任务“宝石能量”后收取邮件。","在家中缝制服饰或给可染色服饰染色，功能与柳巷2号的缝纫机相同。","不是织布机，不能把羊毛加工成布料；遗失后可在秘密森林遗失物品商店花10000金补购。","按缝纫操作完成","https://stardewvalleywiki.com/Sewing_Machine"],
  ["telephone","电话","Telephone","在木匠的商店花2000金直接购买成品，不需要另行学习打造配方。","查询商店当日营业情况、部分库存和升级费用，减少跑空的次数。","绿雨当天不能使用；打电话不算当日聊天，也不增加村民好感度。","不适用","https://stardewvalleywiki.com/Telephone"],
  ["mini-shipping-bin","迷你出货箱","Mini-Shipping Bin","完成“农作物订单”或“皮埃尔优选”特别任务获得，也可在齐先生的核桃房花60颗齐钻购买。","存入可出售物品，在当日结束时随出货统一结算，可放在农场内外。","最多9格，每格可堆叠；结算前可以取回任意格物品，箱内仍有待售物品时不能收起箱子。","日末结算","https://stardewvalleywiki.com/Mini-Shipping_Bin"],
  ["workbench","工作台","Workbench","在木匠的商店花2000金直接购买成品，不需要另行学习打造配方。","打造时直接调用周围邻接宝箱及大箱子里的材料，可合并多个箱子的库存。","可读取相邻8格（包括斜角），不读取祝尼魔宝箱；至少留一个可接近工作台的空位。","按打造操作完成","https://stardewvalleywiki.com/Workbench"],
  ["statue-of-endless-fortune","无尽财富之雕像","Statue Of Endless Fortune","进入赌场后，向店内出售雕像的男子支付1000000金购买，数量不限。","每天生成一件物品；非生日时等概率生成钻石、铱锭、万能晶球或金锭，村民生日时生成其指定最爱。","当天未收取的产物次日会被替换，不会无限堆积；高额购入成本不适合当作短期回本方案。","每天一次","https://stardewvalleywiki.com/Statue_Of_Endless_Fortune"],
  ["return-scepter","回程魔杖","Return Scepter","下水道科罗布斯处花2000000金购买。","将玩家传送到自己的农舍门口；联机农场工人回到自己的小屋门口。","重复使用不消耗，不落在农场图腾传送点；不同于一次性的农场传送图腾。","即时传送","https://stardewvalleywiki.com/Return_Scepter"],
];
for (const [slug, name, originalName, acquisition, effect, limitation, duration, source] of specialEquipmentAdditions) {
  entries.push({ dataset: "items", slug, name, image: `/assets/game/Utility_${slug}.png`, summary: `${name}：${effect}`,
    attributes: { type: "特殊实用设备", 原名: originalName, 获取方式: acquisition, source: acquisition,
      主要用途: effect, 使用限制: limitation, 加工时间: duration, 出售限制: "不可出售",
      新手建议: limitation, 关联规划: `先核对获取条件：${acquisition}再决定是否购买或优先完成对应任务，设备本身不能当作可回收售出的投资。`,
      资料来源: source, links: ["/wiki/items", "/wiki/quests", "/wiki/locations"] }
  });
}

