for (const [slug, name, gameId, acquisition, image] of wallpaperAdditions) {
  const environmental = ['(WP)MoreWalls:15','(WP)MoreWalls:21'].includes(gameId);
  const effect = environmental ? '正常游戏中可见的固定环境样式，用于辨认阁楼装修或诅咒假人改变的墙面，不是可领取、购买或携带的壁纸物品。' : '一次性室内墙面装饰，使用后覆盖选定房间的墙面；配图为该款式的原版纹样，不是新增房间或墙壁的建造材料。';
  entries.push({dataset:'items',slug,name,image,summary:name+'：'+effect,
    attributes:{type:'室内壁纸',游戏物品编号:gameId,获取方式:acquisition,source:acquisition,
      主要用途:effect,使用限制:environmental?'只记录正常游戏可见的环境外观，不能收入背包，不能按普通壁纸购买、领取或铺设。':'壁纸不能堆叠，摆放时需要面向可装饰墙面；家具和设备挡住位置可能妨碍使用。',
      新手建议:environmental?'这是环境样式识别资料，不要为了取得背包物品反复查找商店或目录；请按实际触发条件辨认。':'先对照纹样再领取，走廊与房间可能是不同装饰区域；不需要按墙面格数购买多张同款。',
      关联规划:environmental?'与农舍装修、室内装饰及诅咒假人的行为说明配合阅读；其编号用于区分图案，不代表可以购买。':'先确定壁纸、地板与家具配色，再安排商店、目录或节日兑换；赌场款式需要准备齐币而非金币。',
      资料来源:'https://stardewvalleywiki.com/Wallpaper',links:['/wiki/items','/wiki/locations']}});
}

const farmAnimalAdditions = [
  ["White Chicken","白鸡","animal-white-chicken","鸡舍","在玛妮牧场购买鸡：800金，购买时随机分配颜色；白鸡蛋或大鸡蛋也可孵化白鸡。","每天产白色鸡蛋，友好度与心情足够时可能产大鸡蛋。","孵化需要大鸡舍或高级鸡舍的孵化器，且建筑必须留有动物名额。",3,1,"https://stardewvalleywiki.com/Chicken"],
  ["Brown Chicken","褐鸡","animal-brown-chicken","鸡舍","在玛妮牧场购买鸡：800金，购买时随机分配颜色；褐色蛋及对应大蛋可孵化褐鸡。","每天产褐色鸡蛋，友好度与心情足够时可能产褐色大鸡蛋。","1.6孵化按蛋的颜色决定鸡的颜色；孵化器和鸡舍空位均不可缺少。",3,1,"https://stardewvalleywiki.com/Chicken"],
  ["Blue Chicken","蓝鸡","animal-blue-chicken","鸡舍","看过谢恩8心事件后，在玛妮牧场购买鸡（800金）时有25%机会获得蓝鸡。","每天产白色鸡蛋，不会产蓝色蛋；颜色不同不代表产蛋价格或周期提高。","1.6不能通过孵化获得蓝鸡；未触发谢恩事件时，反复买鸡也不能绕过解锁。",3,1,"https://stardewvalleywiki.com/Chicken"],
  ["Void Chicken","虚空鸡","animal-void-chicken","大鸡舍","将虚空蛋放入鸡舍孵化器，并保留动物空位；不能直接在玛妮牧场购买虚空鸡。","每天产虚空蛋，可继续孵化或加工虚空蛋黄酱，不会产普通大鸡蛋。","先取得虚空蛋再孵化；孵化时间与出生后的成熟期是两段不同的等待。",3,1,"https://stardewvalleywiki.com/Void_Chicken"],
  ["Golden Chicken","金鸡","animal-golden-chicken","大鸡舍","将金蛋放入鸡舍孵化器，并保留动物空位；金蛋获取条件另见金蛋资料，不是普通鸡随机变色。","每天产金蛋；一枚金蛋可加工3份金星蛋黄酱，不能按普通鸡蛋的单份产量估算。","必须先取得金蛋，不能用普通鸡蛋孵出；建筑和孵化器需要满足条件。",3,1,"https://stardewvalleywiki.com/Golden_Chicken"],
  ["Duck","鸭","animal-duck","大鸡舍","玛妮牧场购买：1,200金；也可以将鸭蛋放入鸡舍孵化器，前提是有动物空位。","每2天产鸭蛋，友好度和心情足够时可能改产鸭毛，不是每天同时给两种产品。","鸭子能游泳，但收集鸭蛋与鸭毛仍需要关注生产周期和当天动物状态。",5,2,"https://stardewvalleywiki.com/Duck"],
  ["Rabbit","兔子","animal-rabbit","高级鸡舍","在玛妮牧场以8,000金购买，并安排高级鸡舍空位；不是将兔子的脚放入孵化器。","每4天掉落动物毛；状态足够好时可能改产兔子的脚，不需要用剪刀剪毛。","兔子不会繁殖；兔子的脚不能靠宰杀或孵化取得，不能保证每次都产出。",6,4,"https://stardewvalleywiki.com/Rabbit"],
  ["Dinosaur","恐龙","animal-dinosaur","大鸡舍","将恐龙蛋放入鸡舍孵化器，建筑要有空位；孵化完成即成熟，不在玛妮牧场出售。","每7天产恐龙蛋，可留种孵化或加工恐龙蛋黄酱，不是可战斗的喷火怪物。","孵化时间不等于成熟天数：恐龙出壳后已成熟，但仍需按饲养条件等待产蛋。",0,7,"https://stardewvalleywiki.com/Dinosaur"],
  ["White Cow","白牛","animal-white-cow","畜棚","在玛妮牧场以1,500金购买牛，白色或褐色随机；有条件时也可通过畜棚生育增加数量。","每天产牛奶，状态足够好时产大壶牛奶；用挤奶桶或自动采集器收集。","颜色不改变牛奶种类；不能将牛奶放入孵化器，应保留畜棚空位并喂食。",5,1,"https://stardewvalleywiki.com/Cow"],
  ["Brown Cow","褐牛","animal-brown-cow","畜棚","在玛妮牧场以1,500金购买牛，白色或褐色随机；有条件时也可通过畜棚生育增加数量。","每天产牛奶，状态足够好时产大壶牛奶；与白牛产出相同，不产褐色牛奶。","颜色不改变牛奶种类；用挤奶桶或自动采集器收集，不是直接掉落在地面。",5,1,"https://stardewvalleywiki.com/Cow"],
  ["Goat","山羊","animal-goat","大畜棚","在玛妮牧场以4,000金购买，并安排大畜棚或高级畜棚空位；可以在条件满足时生育。","每2天产羊奶，状态足够好时产大瓶羊奶；用挤奶桶或自动采集器收集。","不要按奶牛的每日周期安排羊奶；成熟、喂食与生产周期都需要满足。",5,2,"https://stardewvalleywiki.com/Goat"],
  ["Sheep","绵羊","animal-sheep","高级畜棚","在玛妮牧场以8,000金购买，并安排高级畜棚空位；剪刀或自动采集器用于收毛。","基础每3天长出动物毛；满足亲密度与牧羊人职业条件时可以缩短周期。","需喂食且心情至少70；友好度至少900减少1天，牧羊人再减少1天，两者叠加可每天产毛。",4,3,"https://stardewvalleywiki.com/Sheep"],
  ["Pig","猪","animal-pig","高级畜棚","在玛妮牧场以16,000金购买，并安排高级畜棚空位；成熟后需能出门活动才能寻找松露。","满足条件时在室外寻找松露，数量并非每天固定；不会在畜棚内直接掉落成品。","冬季和雨天不找松露；需喂食、放出畜棚且有可用空地，不能按每日固定产量承诺收益。",10,1,"https://stardewvalleywiki.com/Pig"],
  ["Ostrich","鸵鸟","animal-ostrich","畜棚","将鸵鸟蛋放入畜棚内的鸵鸟孵化器，普通鸡舍孵化器无效；畜棚需有动物空位。","每7天产鸵鸟蛋；一枚蛋可加工10份同品质蛋黄酱，不能按普通鸡蛋计算。","鸵鸟孵化器配方与首枚鸵鸟蛋分别获取；先解决孵化条件，再规划每周产蛋。",7,7,"https://stardewvalleywiki.com/Ostrich"],
];
for (const [id, name, slug, house, acquisition, effect, restriction, mature, period, sourceUrl] of farmAnimalAdditions) {
  entries.push({ dataset: "items", slug, name, image: `/assets/game/FarmAnimal_${slug}.png`, summary: `${name}：${effect}`,
    attributes: { type: "农场动物", 原版动物编号: id, 住所: house, 成熟天数: mature, 基础生产间隔天数: period,
      获取方式: acquisition, source: acquisition, 主要用途: effect, 饲养限制: restriction,
      新手建议: restriction,
      关联规划: `先安排${house}空位、日常饲料与收集方式，再按成熟期和实际生产条件规划收益；动物售价与产品售价不是同一概念。`,
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/locations"] }
  });
}

